import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"42、【益】 震下巽上","description":"溫公易說 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"溫公易說 - 42、【益】 震下巽上"},"headers":[],"relativePath":"classics/wengong/043.md","filePath":"classics/wengong/043.md"}'),l={name:"classics/wengong/043.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><h3 id="彖曰-益-損上益下-民說無疆。自上下下-其道大光。利有攸往-中正有慶。利渉大川-木道乃行。益動而巽-日進無疆。天施地生-其益無方。凡益之道-與時偕行。" tabindex="-1">彖曰：益，損上益下，民說無疆。自上下下，其道大光。利有攸往，中正有慶。利渉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。 <a class="header-anchor" href="#彖曰-益-損上益下-民說無疆。自上下下-其道大光。利有攸往-中正有慶。利渉大川-木道乃行。益動而巽-日進無疆。天施地生-其益無方。凡益之道-與時偕行。" aria-label="Permalink to “彖曰：益，損上益下，民說無疆。自上下下，其道大光。利有攸往，中正有慶。利渉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。”">​</a></h3><h3 id="象曰-風雷-益。君子以見善則遷-有過則改。" tabindex="-1">象曰：風雷，益。君子以見善則遷，有過則改。 <a class="header-anchor" href="#象曰-風雷-益。君子以見善則遷-有過則改。" aria-label="Permalink to “象曰：風雷，益。君子以見善則遷，有過則改。”">​</a></h3><h3 id="初九-利用為大作-元吉-無咎-象曰-元吉無咎-下不厚事也。" tabindex="-1">初九：利用為大作，元吉，無咎 象曰：元吉無咎，下不厚事也。 <a class="header-anchor" href="#初九-利用為大作-元吉-無咎-象曰-元吉無咎-下不厚事也。" aria-label="Permalink to “初九：利用為大作，元吉，無咎 象曰：元吉無咎，下不厚事也。”">​</a></h3><h3 id="六二-或益之-十朋之龜-弗克違-永貞吉。王用享於帝-吉-象曰-或益之-自外來也。" tabindex="-1">六二：或益之，十朋之龜，弗克違，永貞吉。王用享於帝，吉 象曰：或益之，自外來也。 <a class="header-anchor" href="#六二-或益之-十朋之龜-弗克違-永貞吉。王用享於帝-吉-象曰-或益之-自外來也。" aria-label="Permalink to “六二：或益之，十朋之龜，弗克違，永貞吉。王用享於帝，吉 象曰：或益之，自外來也。”">​</a></h3><h3 id="六三-益之用凶事-無咎-有孚。中行告公-用圭-象曰-益用凶事故有之也。" tabindex="-1">六三：益之用凶事，無咎，有孚。中行告公，用圭 象曰：益用凶事故有之也。 <a class="header-anchor" href="#六三-益之用凶事-無咎-有孚。中行告公-用圭-象曰-益用凶事故有之也。" aria-label="Permalink to “六三：益之用凶事，無咎，有孚。中行告公，用圭 象曰：益用凶事故有之也。”">​</a></h3><h3 id="六四-中行告公-從利為依。遷國-象曰-告公從以益志也。" tabindex="-1">六四：中行告公，從利為依。遷國 象曰：告公從以益志也。 <a class="header-anchor" href="#六四-中行告公-從利為依。遷國-象曰-告公從以益志也。" aria-label="Permalink to “六四：中行告公，從利為依。遷國 象曰：告公從以益志也。”">​</a></h3><h3 id="九五-有孚惠心-勿問-元吉。有孚惠我德-象曰-有孚惠心-勿問之矣。惠我德-大得志也。" tabindex="-1">九五：有孚惠心，勿問，元吉。有孚惠我德 象曰：有孚惠心，勿問之矣。惠我德，大得志也。 <a class="header-anchor" href="#九五-有孚惠心-勿問-元吉。有孚惠我德-象曰-有孚惠心-勿問之矣。惠我德-大得志也。" aria-label="Permalink to “九五：有孚惠心，勿問，元吉。有孚惠我德 象曰：有孚惠心，勿問之矣。惠我德，大得志也。”">​</a></h3><p>惠心者何？惠之所施，孚於心然後善也。夫人墜於絶壑而遺之珠玉，寢疾垂死而饋之酒肉，其物非不美也，而人不以德者何也？非其心之所欲也。</p><h3 id="上九-莫益之-或擊之。立心勿恆-兇-象曰-莫益之-偏辭也。或擊之-自外來也。" tabindex="-1">上九：莫益之，或擊之。立心勿恆，兇 象曰：莫益之，偏辭也。或擊之，自外來也。 <a class="header-anchor" href="#上九-莫益之-或擊之。立心勿恆-兇-象曰-莫益之-偏辭也。或擊之-自外來也。" aria-label="Permalink to “上九：莫益之，或擊之。立心勿恆，兇 象曰：莫益之，偏辭也。或擊之，自外來也。”">​</a></h3><p>上九立心勿恆，兇何也？戒人勿以求益為常心也。莫益之，偏辭者何也？知益於已而不知恕於人之謂也。</p>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
